namespace enclosure {


constexpr int SIZE = 19;
constexpr int MAX_MOVES = 120;
constexpr int HISTORY_TURNS = 4;  // engine.HISTORY_TURNS
constexpr int NOFF = 48;
constexpr int PASS = SIZE * SIZE * NOFF;
constexpr int PLANES = 4 * NOFF + 5;
constexpr int SCALARS = 5;
constexpr int MAX_OBS_IDX = 256;  // Set bits per observation: at most 2 per edge.
constexpr double EPSILON = 1e-9;
constexpr int PAD = 6;
constexpr int GRID = SIZE + 2 * PAD;

struct Off { int dx, dy; };
inline Off OFFS[NOFF];
inline int OFF_INDEX[7][7];
inline int INTERIOR_N[NOFF];
inline Off INTERIOR[NOFF][2];
inline std::vector<int> CROSSINGS[NOFF];  // Per enemy-edge offset: relative candidate indices.

inline long long cross(long long ax, long long ay, long long bx, long long by, long long cx, long long cy) {
  return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
}

inline bool on_segment(int px, int py, int ax, int ay, int bx, int by) {
  return cross(ax, ay, bx, by, px, py) == 0 && std::min(ax, bx) <= px && px <= std::max(ax, bx) &&
         std::min(ay, by) <= py && py <= std::max(ay, by);
}

// Closed segment intersection: touching an endpoint counts (engine.intersects).
inline bool intersects(int ax, int ay, int bx, int by, int cx, int cy, int dx, int dy) {
  long long d1 = cross(ax, ay, bx, by, cx, cy), d2 = cross(ax, ay, bx, by, dx, dy);
  long long d3 = cross(cx, cy, dx, dy, ax, ay), d4 = cross(cx, cy, dx, dy, bx, by);
  if (((d1 < 0 && d2 > 0) || (d1 > 0 && d2 < 0)) && ((d3 < 0 && d4 > 0) || (d3 > 0 && d4 < 0)))
    return true;
  return on_segment(cx, cy, ax, ay, bx, by) || on_segment(dx, dy, ax, ay, bx, by) ||
         on_segment(ax, ay, cx, cy, dx, dy) || on_segment(bx, by, cx, cy, dx, dy);
}

inline int igcd(int a, int b) { return b ? igcd(b, a % b) : (a < 0 ? -a : a); }

struct Tables {
  Tables() {
    int i = 0;
    for (int dx = -3; dx <= 3; ++dx)
      for (int dy = -3; dy <= 3; ++dy)
        if (std::max(std::abs(dx), std::abs(dy)) > 0) OFFS[i++] = {dx, dy};
    for (auto& row : OFF_INDEX) for (int& v : row) v = -1;
    for (int k = 0; k < NOFF; ++k) {
      OFF_INDEX[OFFS[k].dx + 3][OFFS[k].dy + 3] = k;
      int g = igcd(std::abs(OFFS[k].dx), std::abs(OFFS[k].dy));
      INTERIOR_N[k] = g - 1;
      for (int s = 1; s < g; ++s) INTERIOR[k][s - 1] = {OFFS[k].dx * s / g, OFFS[k].dy * s / g};
    }
    // Candidate 0 -> oc hits enemy edge r -> r + oe (translation invariance).
    for (int oe = 0; oe < NOFF; ++oe)
      for (int rx = -6; rx <= 6; ++rx)
        for (int ry = -6; ry <= 6; ++ry)
          for (int oc = 0; oc < NOFF; ++oc)
            if (intersects(0, 0, OFFS[oc].dx, OFFS[oc].dy, rx, ry, rx + OFFS[oe].dx, ry + OFFS[oe].dy))
              CROSSINGS[oe].push_back((-rx * GRID - ry) * NOFF + oc);
  }
};
inline Tables tables;

// Canonical undirected edge: (ax, ay) < (bx, by) lexicographically.
struct Edge {
  int8_t ax, ay, bx, by;
  bool operator==(const Edge& o) const { return ax == o.ax && ay == o.ay && bx == o.bx && by == o.by; }
};

inline Edge make_edge(int ax, int ay, int bx, int by) {
  if (std::tie(bx, by) < std::tie(ax, ay)) { std::swap(ax, bx); std::swap(ay, by); }
  return Edge{int8_t(ax), int8_t(ay), int8_t(bx), int8_t(by)};
}

inline bool contains(const std::vector<Edge>& v, const Edge& e) {
  return std::find(v.begin(), v.end(), e) != v.end();
}

inline double snap(double v) { return std::nearbyint(v / EPSILON) * EPSILON; }  // Round half to even, as Python.

// --- Enclosed area --------------------------------------------------------
//
// Own edges only meet at shared endpoints or cross at interior points (an
// endpoint may not lie inside an own edge, nor a node inside a new edge), so
// the arrangement's vertices are endpoints and exact rational crossings.
// Faces are traced with half-edges; the union of enclosed regions is the sum
// of bounded face cycles minus the outer cycles of components that sit inside
// another component's face (they are holes there and faces of their own).

struct RPt {
  long long x, y, d;  // (x / d, y / d), d > 0, reduced.
  bool operator<(const RPt& o) const { return std::tie(x, y, d) < std::tie(o.x, o.y, o.d); }
};

inline long long lgcd(long long a, long long b) {
  a = a < 0 ? -a : a; b = b < 0 ? -b : b;
  while (b) { long long t = a % b; a = b; b = t; }
  return a;
}

inline RPt reduce(long long x, long long y, long long d) {
  if (d < 0) { x = -x; y = -y; d = -d; }
  long long g = lgcd(lgcd(x, y), d);
  if (g > 1) { x /= g; y /= g; d /= g; }
  return {x, y, d};
}

// Lattice points on the given edges (nodes and points inside them): on[x * SIZE + y].
inline void edge_points(const std::vector<Edge>& edges, uint8_t* on) {
  std::fill(on, on + SIZE * SIZE, 0);
  for (const Edge& e : edges) {
    int dx = e.bx - e.ax, dy = e.by - e.ay, g = igcd(std::abs(dx), std::abs(dy));
    for (int s = 0; s <= g; ++s) on[(e.ax + dx * s / g) * SIZE + e.ay + dy * s / g] = 1;
  }
}

// With `inside` (x * SIZE + y), also marks the lattice points strictly inside
// the enclosed regions (planes.enclosed_points): the union of regions is the
// union of the positive face cycles taken as polygons, since a face's holes
// are faces of the components nested in them.
inline double enclosed_area(const std::vector<Edge>& edges, uint8_t* inside_points = nullptr) {
  const int n = int(edges.size());
  if (inside_points) std::fill(inside_points, inside_points + SIZE * SIZE, 0);
  if (n < 3) return 0.0;
  std::map<RPt, int> index;
  std::vector<double> vx, vy;
  auto vertex = [&](const RPt& p) {
    auto it = index.find(p);
    if (it != index.end()) return it->second;
    int id = int(vx.size());
    index.emplace(p, id);
    vx.push_back(double(p.x) / double(p.d));
    vy.push_back(double(p.y) / double(p.d));
    return id;
  };
  // Points along each segment, with their parameter t in [0, 1].
  std::vector<std::vector<std::pair<double, int>>> along(n);
  for (int i = 0; i < n; ++i) {
    const Edge& e = edges[i];
    along[i].push_back({0.0, vertex(reduce(e.ax, e.ay, 1))});
    along[i].push_back({1.0, vertex(reduce(e.bx, e.by, 1))});
  }
  for (int i = 0; i < n; ++i) {
    const Edge& e = edges[i];
    for (int j = i + 1; j < n; ++j) {
      const Edge& f = edges[j];
      long long ex = e.bx - e.ax, ey = e.by - e.ay, fx = f.bx - f.ax, fy = f.by - f.ay;
      long long den = ex * fy - ey * fx;
      if (den != 0) {
        long long tn = (f.ax - e.ax) * fy - (f.ay - e.ay) * fx;  // t = tn / den along e
        long long un = (f.ax - e.ax) * ey - (f.ay - e.ay) * ex;  // u = un / den along f
        bool t_in = den > 0 ? (tn > 0 && tn < den) : (tn < 0 && tn > den);
        bool u_in = den > 0 ? (un > 0 && un < den) : (un < 0 && un > den);
        bool t_end = tn == 0 || tn == den, u_end = un == 0 || un == den;
        bool t_ok = den > 0 ? (tn >= 0 && tn <= den) : (tn <= 0 && tn >= den);
        bool u_ok = den > 0 ? (un >= 0 && un <= den) : (un <= 0 && un >= den);
        if (!(t_ok && u_ok) || (t_end && u_end)) continue;  // Apart, or a shared endpoint.
        (void)t_in; (void)u_in;
        RPt p = reduce(e.ax * den + tn * ex, e.ay * den + tn * ey, den);
        int id = vertex(p);
        double t = double(tn) / double(den), u = double(un) / double(den);
        if (!t_end) along[i].push_back({t, id});
        if (!u_end) along[j].push_back({u, id});
      }
      // Parallel edges cannot overlap (no node may lie inside an own edge).
    }
  }
  // Sub-edges between consecutive points on each segment.
  const int nv = int(vx.size());
  std::vector<std::vector<int>> out(nv);  // outgoing half-edge ids per vertex
  std::vector<int> from, to;
  for (auto& pts : along) {
    std::sort(pts.begin(), pts.end());
    for (size_t k = 0; k + 1 < pts.size(); ++k) {
      int a = pts[k].second, b = pts[k + 1].second;
      if (a == b) continue;
      out[a].push_back(int(from.size())); from.push_back(a); to.push_back(b);
      out[b].push_back(int(from.size())); from.push_back(b); to.push_back(a);
    }
  }
  const int nh = int(from.size());
  std::vector<double> angle(nh);
  for (int h = 0; h < nh; ++h) angle[h] = std::atan2(vy[to[h]] - vy[from[h]], vx[to[h]] - vx[from[h]]);
  std::vector<int> pos_in(nh);
  for (int v = 0; v < nv; ++v) {
    std::sort(out[v].begin(), out[v].end(), [&](int a, int b) { return angle[a] < angle[b]; });
    for (int k = 0; k < int(out[v].size()); ++k) pos_in[out[v][k]] = k;
  }
  // Components (union-find over vertices).
  std::vector<int> parent(nv);
  std::iota(parent.begin(), parent.end(), 0);
  std::function<int(int)> find = [&](int v) { return parent[v] == v ? v : parent[v] = find(parent[v]); };
  for (int h = 0; h < nh; h += 2) parent[find(from[h])] = find(to[h]);
  // Trace face cycles: next(u -> v) = the outgoing edge at v just clockwise of v -> u.
  std::vector<char> seen(nh, 0);
  struct Cycle { double area; int comp; std::vector<int> verts; };
  std::vector<Cycle> cycles;
  for (int h0 = 0; h0 < nh; ++h0) {
    if (seen[h0]) continue;
    Cycle c{0.0, find(from[h0]), {}};
    int h = h0;
    while (!seen[h]) {
      seen[h] = 1;
      c.verts.push_back(from[h]);
      c.area += vx[from[h]] * vy[to[h]] - vx[to[h]] * vy[from[h]];
      int v = to[h], twin = h ^ 1;
      int k = pos_in[twin];
      int deg = int(out[v].size());
      h = out[v][(k - 1 + deg) % deg];
    }
    c.area *= 0.5;
    cycles.push_back(std::move(c));
  }
  // Outer cycle of each component: its most negative cycle.
  std::map<int, int> outer;
  for (int i = 0; i < int(cycles.size()); ++i) {
    auto it = outer.find(cycles[i].comp);
    if (it == outer.end() || cycles[i].area < cycles[it->second].area) outer[cycles[i].comp] = i;
  }
  auto inside = [&](double px, double py, const std::vector<int>& poly) {
    bool in = false;
    for (size_t a = 0, b = poly.size() - 1; a < poly.size(); b = a++) {
      double xa = vx[poly[a]], ya = vy[poly[a]], xb = vx[poly[b]], yb = vy[poly[b]];
      if ((ya > py) != (yb > py) && px < (xb - xa) * (py - ya) / (yb - ya) + xa) in = !in;
    }
    return in;
  };
  if (inside_points) {
    uint8_t on[SIZE * SIZE];
    edge_points(edges, on);
    for (int x = 0; x < SIZE; ++x)
      for (int y = 0; y < SIZE; ++y) {
        if (on[x * SIZE + y]) continue;
        for (auto& c : cycles)
          if (c.area > 0 && inside(x, y, c.verts)) { inside_points[x * SIZE + y] = 1; break; }
      }
  }
  double total = 0.0;
  for (auto& c : cycles)
    if (c.area > 0) total += c.area;
  for (auto& [comp, oi] : outer) {
    const Cycle& o = cycles[oi];
    if (o.area >= 0) continue;
    double px = vx[o.verts[0]], py = vy[o.verts[0]];
    for (auto& c : cycles)
      if (c.area > 0 && c.comp != comp && inside(px, py, c.verts)) { total += o.area; break; }
  }
  return snap(total);
}

// --- Position -------------------------------------------------------------

struct Position {
  std::vector<Edge> edges[2];
  std::vector<Edge> protected_, placed;
  double scores[2] = {0.0, 0.0};
  int player = 0, moves_left = 1, move_count = 0;
  double areas[2] = {0.0, 0.0};
  bool area_ok[2] = {true, true};
  // Edges placed in earlier turns, newest first (engine.Position.history): turn h
  // is the one h + 1 turns before protected_. A turn places at most two edges.
  // Network input only; the rules never read it. Fixed arrays: no allocation when
  // the search copies positions.
  Edge history[HISTORY_TURNS][2];
  uint8_t history_n[HISTORY_TURNS] = {};

  std::vector<Edge> history_turn(int h) const { return {history[h], history[h] + history_n[h]}; }

  Position() {
    edges[0].push_back(make_edge(0, 9, 3, 9));
    edges[1].push_back(make_edge(15, 9, 18, 9));
  }

  bool terminal() const { return move_count >= MAX_MOVES; }

  double area(int p) {
    if (!area_ok[p]) { areas[p] = enclosed_area(edges[p]); area_ok[p] = true; }
    return areas[p];
  }

  void legal_actions(std::vector<int>& out) const {
    out.clear();
    if (terminal()) return;
    const auto& own = edges[player];
    const auto& enemy = edges[1 - player];
    bool node[SIZE][SIZE] = {};
    bool inside_own[SIZE][SIZE] = {};
    static thread_local std::vector<uint64_t> own_dir;  // bitmask of offsets per point
    own_dir.assign(SIZE * SIZE, 0);
    for (const Edge& e : own) {
      node[e.ax][e.ay] = node[e.bx][e.by] = true;
      int k = OFF_INDEX[e.bx - e.ax + 3][e.by - e.ay + 3];
      int kr = OFF_INDEX[e.ax - e.bx + 3][e.ay - e.by + 3];
      own_dir[e.ax * SIZE + e.ay] |= 1ull << k;
      own_dir[e.bx * SIZE + e.by] |= 1ull << kr;
      for (int s = 0; s < INTERIOR_N[k]; ++s) inside_own[e.ax + INTERIOR[k][s].dx][e.ay + INTERIOR[k][s].dy] = true;
    }
    static thread_local std::vector<int16_t> hits, blocked;
    static thread_local std::vector<int> touched;
    if (hits.empty()) { hits.assign(GRID * GRID * NOFF, 0); blocked.assign(GRID * GRID * NOFF, 0); }
    touched.clear();
    for (const Edge& e : enemy) {
      int oe = OFF_INDEX[e.bx - e.ax + 3][e.by - e.ay + 3];
      int base = ((e.ax + PAD) * GRID + e.ay + PAD) * NOFF;
      bool guarded = contains(protected_, e);
      for (int rel : CROSSINGS[oe]) {
        int idx = base + rel;
        if (!hits[idx] && !blocked[idx]) touched.push_back(idx);
        ++hits[idx];
        if (guarded) ++blocked[idx];
      }
    }
    for (int ax = 0; ax < SIZE; ++ax)
      for (int ay = 0; ay < SIZE; ++ay) {
        if (!node[ax][ay] || inside_own[ax][ay]) continue;
        for (int k = 0; k < NOFF; ++k) {
          int bx = ax + OFFS[k].dx, by = ay + OFFS[k].dy;
          if (bx < 0 || bx >= SIZE || by < 0 || by >= SIZE) continue;
          bool b_first = bx < ax || (bx == ax && by < ay);
          if (node[bx][by] && b_first) continue;
          if (own_dir[ax * SIZE + ay] >> k & 1) continue;
          if (inside_own[bx][by]) continue;
          bool blocked_node = false;
          for (int s = 0; s < INTERIOR_N[k]; ++s)
            if (node[ax + INTERIOR[k][s].dx][ay + INTERIOR[k][s].dy]) blocked_node = true;
          if (blocked_node) continue;
          int idx = ((ax + PAD) * GRID + ay + PAD) * NOFF + k;
          if (hits[idx] > 1 || blocked[idx] > 0) continue;
          out.push_back((ay * SIZE + ax) * NOFF + k);
        }
      }
    for (int idx : touched) hits[idx] = blocked[idx] = 0;
    std::sort(out.begin(), out.end());
    if (out.empty()) out.push_back(PASS);
  }

  void end_turn() {
    for (int p = 0; p < 2; ++p) scores[p] = snap(scores[p] + area(p));
    for (int h = HISTORY_TURNS - 1; h > 0; --h) {
      history_n[h] = history_n[h - 1];
      history[h][0] = history[h - 1][0];
      history[h][1] = history[h - 1][1];
    }
    history_n[0] = uint8_t(std::min<size_t>(2, protected_.size()));
    for (int i = 0; i < history_n[0]; ++i) history[0][i] = protected_[i];
    protected_ = placed;
    placed.clear();
    player = 1 - player;
    moves_left = std::min(2, MAX_MOVES - move_count);
  }

  void forfeit_turn() {
    move_count += moves_left;
    end_turn();
  }

  // Plays a legal action (legality is not re-checked).
  void play(int action) {
    if (action == PASS) { forfeit_turn(); return; }
    int cell = action / NOFF, k = action % NOFF;
    int ax = cell % SIZE, ay = cell / SIZE;
    int bx = ax + OFFS[k].dx, by = ay + OFFS[k].dy;
    auto& own = edges[player];
    auto& enemy = edges[1 - player];
    for (size_t i = 0; i < enemy.size(); ++i) {
      const Edge& e = enemy[i];
      if (intersects(ax, ay, bx, by, e.ax, e.ay, e.bx, e.by)) {
        enemy.erase(enemy.begin() + i);
        area_ok[1 - player] = false;
        break;
      }
    }
    bool changes = false;
    for (const Edge& e : own) {
      if ((e.ax == bx && e.ay == by) || (e.bx == bx && e.by == by)) { changes = true; break; }
      bool has_a = (e.ax == ax && e.ay == ay) || (e.bx == ax && e.by == ay);
      if (!has_a && intersects(ax, ay, bx, by, e.ax, e.ay, e.bx, e.by)) { changes = true; break; }
    }
    if (changes) area_ok[player] = false;
    Edge e = make_edge(ax, ay, bx, by);
    own.push_back(e);
    placed.push_back(e);
    ++move_count;
    if (--moves_left == 0) end_turn();
  }

  float result() const {  // Player 0's return at the end.
    return scores[0] > scores[1] ? 1.f : scores[0] < scores[1] ? -1.f : 0.f;
  }

  // Set-bit indices of the channels-last observation (engine.write_observation).
  int observation(int32_t* idx, float* scalars) const {
    int n = 0;
    for (int owner = 0; owner < 2; ++owner)
      for (const Edge& e : edges[owner]) {
        int k = OFF_INDEX[e.bx - e.ax + 3][e.by - e.ay + 3];
        int base = (e.ay * SIZE + e.ax) * PLANES;
        idx[n++] = base + owner * NOFF + k;
        if (contains(protected_, e) || contains(placed, e)) idx[n++] = base + (owner + 2) * NOFF + k;
      }
    scalars[0] = float(player);
    scalars[1] = float(moves_left / 2.0);
    scalars[2] = float(double(move_count) / MAX_MOVES);
    scalars[3] = float(scores[0] / (18 * 18 * 61));
    scalars[4] = float(scores[1] / (18 * 18 * 61));
    return n;
  }
};

}  // namespace enclosure
